const maintenanceItems = $node['Fetch Due Services'].json;
const insuranceItems = $node['Fetch Insurance Expiries'].json;
const pucItems = $node['Fetch PUC Expiries'].json;
const fastagItems = $node['Fetch FASTag Accounts'].json;

const now = new Date();
const results = [];

// 1. Process Maintenance Schedules
if (Array.isArray(maintenanceItems)) {
  for (const item of maintenanceItems) {
    if (!item.id || !item.vehicles) continue;
    results.push({
      json: {
        entity_type: 'maintenance',
        entity_id: item.id,
        user_id: item.vehicles.user_id,
        vehicle_model: item.vehicles.model,
        status: item.status,
        due_date: item.due_date,
        message: `Reminder: Maintenance item '${item.task_name || 'Service'}' for vehicle ${item.vehicles.model || ''} is currently ${item.status}. Due on ${item.due_date || 'N/A'}.`,
      }
    });
  }
}

// 2. Process Insurance Policies
if (Array.isArray(insuranceItems)) {
  for (const item of insuranceItems) {
    if (!item.id || !item.vehicles || !item.expiry_date) continue;
    const expDate = new Date(item.expiry_date);
    const diffDays = Math.ceil((expDate - now) / (1000 * 60 * 60 * 24));
    if (diffDays <= 30) {
      const status = diffDays < 0 ? 'expired' : 'due_soon';
      results.push({
        json: {
          entity_type: 'insurance',
          entity_id: item.id,
          user_id: item.vehicles.user_id,
          vehicle_model: item.vehicles.model,
          status: status,
          due_date: item.expiry_date,
          message: `Insurance Reminder: Policy ${item.policy_number || ''} for vehicle ${item.vehicles.model || ''} is ${status} (Expiry: ${item.expiry_date}).`,
        }
      });
    }
  }
}

// 3. Process PUC Certificates
if (Array.isArray(pucItems)) {
  for (const item of pucItems) {
    if (!item.id || !item.vehicles || !item.expiry_date) continue;
    const expDate = new Date(item.expiry_date);
    const diffDays = Math.ceil((expDate - now) / (1000 * 60 * 60 * 24));
    if (diffDays <= 15) {
      const status = diffDays < 0 ? 'expired' : 'due_soon';
      results.push({
        json: {
          entity_type: 'puc',
          entity_id: item.id,
          user_id: item.vehicles.user_id,
          vehicle_model: item.vehicles.model,
          status: status,
          due_date: item.expiry_date,
          message: `PUC Reminder: Certificate ${item.puc_number || ''} for vehicle ${item.vehicles.model || ''} is ${status} (Expiry: ${item.expiry_date}).`,
        }
      });
    }
  }
}

// 4. Process FASTag Accounts
if (Array.isArray(fastagItems)) {
  for (const item of fastagItems) {
    if (!item.id || !item.vehicles) continue;
    const balance = parseFloat(item.balance || 0);
    if (balance < 200 || item.status === 'low_balance' || item.status === 'expired') {
      results.push({
        json: {
          entity_type: 'fastag',
          entity_id: item.id,
          user_id: item.vehicles.user_id,
          vehicle_model: item.vehicles.model,
          status: item.status || 'low_balance',
          due_date: item.updated_at || new Date().toISOString(),
          message: `FASTag Alert: Account for vehicle ${item.vehicles.model || ''} has low balance (₹${balance}). Please recharge soon.`,
        }
      });
    }
  }
}

return results;

const items = $input.all();
const results = [];
const notifiedCache = $getWorkflowStaticData('global').notifiedCache || {};
const newNotifiedCache = {};
const todayStr = new Date().toISOString().split('T')[0];

for (const item of items) {
  const json = item.json;
  const cacheKey = `${json.entity_type}_${json.entity_id}`;
  const status = json.status;

  // Deduplication: Only notify once every 7 days for warnings, or 3 days for critical overdue/expired items
  const lastNotified = notifiedCache[cacheKey];
  let shouldNotify = true;

  if (lastNotified) {
    const diffTime = Math.abs(new Date(todayStr) - new Date(lastNotified));
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    const limit = (status === 'overdue' || status === 'expired') ? 3 : 7;
    if (diffDays < limit) {
      shouldNotify = false;
    }
  }

  if (shouldNotify) {
    newNotifiedCache[cacheKey] = todayStr;
    results.push(item);
  } else {
    newNotifiedCache[cacheKey] = lastNotified;
  }
}

$getWorkflowStaticData('global').notifiedCache = newNotifiedCache;
return results;

